import React from "react";

function Team() {
  return (
    <div className="container">
      <div className="row p-3 mt-5 border-top">
        <h1 className="text-center">People</h1>
      </div>

      <div
        className="row p-3 text-muted"
        style={{ lineHeight: "1.8", fontSize: "1.2em" }}
      >
        <div className="col-12 col-md-6 p-3 text-center">
          <div style={styles.imageWrapper}>
            <img
              src="media/images/profile-image copy.png"
              alt="Aaditya Bhardwaj"
              style={styles.profileImage}
            />
          </div>

          <h4 className="mt-5">Aaditya Bhardwaj</h4>
          <h6>Founder, CEO</h6>
        </div>
        <div className="col-6 p-3">
          <p>
            Nithin bootstrapped and founded Zerodha in 2010 to overcome the
            hurdles he faced during his decade long stint as a trader. Today,
            Zerodha has changed the landscape of the Indian broking
            industry.{" "}
          </p>
          <p>
            He is a member of the SEBI Secondary Market Advisory Committee
            (SMAC) and the Market Data Advisory Committee (MDAC).{" "}
          </p>{" "}
          <p>Playing basketball is his zen.</p>{" "}
          <p>
            Connect on{" "}
            <a href="" style={{ textDecoration: "none" }}>
              Homepage / TradingQnA / Twitter
            </a>
          </p>
        </div>
      </div>
    </div>
  );
}

export default Team;

const styles = {
  imageWrapper: {
    position: "relative",
    display: "inline-block",
    width: "220px", // Exact dimensions used by Zerodha for profile circles
    height: "220px",
    margin: "0 auto",
  },
  profileImage: {
    width: "100%",
    height: "100%",
    borderRadius: "50%", // Forces a perfect circular clip-path shape
    objectFit: "cover", // Prevents your face from stretching or compressing
    objectPosition: "center", // Keeps your eyes and nose centered in the frame
  },
};
